package org.eclipse.rdf4j.sail.lmdb.benchmark;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;

import java.util.Arrays;
import java.util.List;

import org.eclipse.rdf4j.query.algebra.evaluation.impl.DefaultEvaluationStrategyFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbCacheImplementation;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;
import org.openjdk.jmh.annotations.Param;

class DatagovCacheSelectionTest {

	@Test
	void benchmarkDefaultsIncludeEverySelectableCache() throws Exception {
		Param parameter = DatagovLoadIsolationBenchmark.class.getField("cacheImplementation")
				.getAnnotation(Param.class);
		assertArrayEquals(Arrays.stream(LmdbCacheImplementation.values()).map(Enum::name).toArray(String[]::new),
				parameter.value());
	}

	@ParameterizedTest
	@EnumSource(LmdbCacheImplementation.class)
	void allConfigurationPathsUseTheSelectedBackend(LmdbCacheImplementation implementation) {
		DatagovLoadIsolationBenchmark benchmark = new DatagovLoadIsolationBenchmark();
		benchmark.cacheImplementation = implementation;
		benchmark.bulkOperationSize = 17;
		for (boolean automatic : List.of(true, false)) {
			benchmark.automaticEvaluationStrategy = automatic;
			for (LmdbStoreConfig config : List.of(benchmark.createBenchmarkConfig(),
					benchmark.createBenchmarkConfigAllIndexes())) {
				assertEquals(implementation, config.getCacheImplementation());
				assertEquals(17, config.getBulkOperationSize());
				assertFalse(config.getForceSync());
				config.validate();
				if (automatic) {
					assertNull(config.getEvaluationStrategyFactoryClassName());
				} else {
					assertEquals(DefaultEvaluationStrategyFactory.class.getName(),
							config.getEvaluationStrategyFactoryClassName());
				}
			}
		}
	}
}
